import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function AddProduct() {
  const [name, setName] = useState("");
  const [desc, setDesc] = useState("");
  const [price, setPrice] = useState("");
  const [discount, setDiscount] = useState("");
  const [category, setCategory] = useState("");
  const [brand, setBrand] = useState("");
  const [sizes, setSizes] = useState(""); // CSV
  const [colors, setColors] = useState(""); // CSV or color values
  const [images, setImages] = useState(""); // CSV of image URLs
  const [stock, setStock] = useState(0);
  const navigate = useNavigate();

  const saveLocalProduct = (p) => {
    const key = "localProducts";
    const existing = JSON.parse(localStorage.getItem(key) || "[]");
    existing.unshift(p);
    localStorage.setItem(key, JSON.stringify(existing));
  };

  const onSubmit = (e) => {
    e.preventDefault();
    if (!name || !price || !category) {
      alert("Name, price and category are required");
      return;
    }
    const product = {
      id: "local-" + Date.now(),
      name: name.trim(),
      description: desc.trim(),
      price: Number(price) || 0,
      discount_price: discount ? Number(discount) : null,
      category: category.trim(),
      brand: brand.trim(),
      sizes: sizes ? sizes.split(",").map(s => s.trim()).filter(Boolean) : [],
      colors: colors ? colors.split(",").map(c => c.trim()).filter(Boolean) : [],
      images: images ? images.split(",").map(i => i.trim()).filter(Boolean) : ["/images/placeholder.png"],
      stock: Number(stock) || 0,
      rating: 0,
      reviews: 0
    };
    saveLocalProduct(product);
    alert("Product added locally");
    navigate("/products");
  };

  return (
    <div className="container" style={{ maxWidth: 760 }}>
      <h2>Add Product (local)</h2>
      <form onSubmit={onSubmit} style={{ display: "grid", gap: 10 }}>
        <input placeholder="Name" value={name} onChange={e=>setName(e.target.value)} />
        <input placeholder="Brand" value={brand} onChange={e=>setBrand(e.target.value)} />
        <input placeholder="Category (e.g. Men, Women, Shoes)" value={category} onChange={e=>setCategory(e.target.value)} />
        <textarea placeholder="Short description" value={desc} onChange={e=>setDesc(e.target.value)} />
        <div style={{ display:"flex", gap:8 }}>
          <input placeholder="Price" value={price} onChange={e=>setPrice(e.target.value)} />
          <input placeholder="Discount price (optional)" value={discount} onChange={e=>setDiscount(e.target.value)} />
          <input placeholder="Stock" value={stock} onChange={e=>setStock(e.target.value)} />
        </div>
        <input placeholder="Sizes (comma separated, e.g. S,M,L,XL)" value={sizes} onChange={e=>setSizes(e.target.value)} />
        <input placeholder="Colors (comma separated or hex, e.g. Red,#000)" value={colors} onChange={e=>setColors(e.target.value)} />
        <input placeholder="Image URLs (comma separated)" value={images} onChange={e=>setImages(e.target.value)} />
        <div style={{ display:"flex", gap:8 }}>
          <button className="btn" type="submit">Save product</button>
          <button className="btn secondary" type="button" onClick={()=>{ setName(""); setDesc(""); setPrice(""); setDiscount(""); setCategory(""); setBrand(""); setSizes(""); setColors(""); setImages(""); setStock(0); }}>
            Clear
          </button>
        </div>
      </form>
    </div>
  );
}
